/**
 * Дистанция между двумя GPS точками в метрах
 * @param {Array<number>} latLon1
 * @param {Array<number>} latLon2
 * @returns {number}
 * @link https://www.movable-type.co.uk/scripts/latlong.html
 */
export function getDistanceBetweenPointsInMeters(
  [lat1, lon1]: [number, number, number?],
  [lat2, lon2]: [number, number, number?],
) {
  const R = 6371e3; // metres
  const φ1 = (lat1 * Math.PI) / 180; // φ, λ in radians
  const φ2 = (lat2 * Math.PI) / 180;
  const Δφ = ((lat2 - lat1) * Math.PI) / 180;
  const Δλ = ((lon2 - lon1) * Math.PI) / 180;

  const a =
    Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
    Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  const d = R * c; // in metres

  return d;
}

export function getDistanceByCoordsInMeters(latLonArray: [number, number][]) {
  return latLonArray.reduce((acc, cur, index, arr) => {
    if (index === 0) {
      return acc;
    }

    return acc + getDistanceBetweenPointsInMeters(arr[index - 1], cur);
  }, 0);
}

export function getBounds(points: [number, number][]) {
  const n = points.length;
  if (n === 0) {
    return [];
  }
  const d = points[0].length;
  const lo = points[0].slice();
  const hi = points[0].slice();
  for (let i = 1; i < n; ++i) {
    const p = points[i];
    for (let j = 0; j < d; ++j) {
      const x = p[j];
      lo[j] = Math.min(lo[j], x);
      hi[j] = Math.max(hi[j], x);
    }
  }
  return [lo, hi];
}

/**
 * Оптимизированный алгоритм LTTB для GPS-треков в формате [latitude, longitude][]
 * @param data Исходный массив координат
 * @param threshold До скольки точек нужно сжать трек (должно быть >= 3)
 */
export function lttbGPS(data: [number, number][], threshold: number): [number, number][] {
  const dataLen = data.length;

  // Если точек меньше порога, возвращаем копию трека
  if (threshold >= dataLen || threshold < 3) {
    return [...data];
  }

  // Заранее выделяем фиксированный массив под ссылки на результаты
  const sampled: [number, number][] = new Array(threshold);

  // Первая точка всегда берется из оригинала
  sampled[0] = data[0];

  // Вычисляем шаг бакета (исключая первую и последнюю точки)
  const bucketSize = (dataLen - 2) / (threshold - 2);
  let sampledIndex = 1;

  // Точка A (предыдущая выбранная точка)
  let aLat = data[0][0];
  let aLng = data[0][1];

  for (let i = 0; i < threshold - 2; i++) {
    // -------------------------------------------------------------
    // 1. НАХОДИМ ЦЕНТР МАСС СЛЕДУЮЩЕГО БАКЕТА (Bucket C)
    // -------------------------------------------------------------
    const cStartIndex = Math.floor((i + 1) * bucketSize) + 1;
    let cEndIndex = Math.floor((i + 2) * bucketSize) + 1;
    if (cEndIndex > dataLen) cEndIndex = dataLen;

    let cLatSum = 0;
    let cLngSum = 0;
    const cBucketSize = cEndIndex - cStartIndex;

    for (let c = cStartIndex; c < cEndIndex; c++) {
      cLatSum += data[c][0];
      cLngSum += data[c][1];
    }

    const cAvgLat = cLatSum / cBucketSize;
    const cAvgLng = cLngSum / cBucketSize;

    // -------------------------------------------------------------
    // 2. ИЩЕМ ТОЧКУ В ТЕКУЩЕМ БАКЕТЕ (Bucket B), МАКСИМИЗИРУЮЩУЮ ПЛОЩАДЬ
    // -------------------------------------------------------------
    const bStartIndex = Math.floor(i * bucketSize) + 1;
    const bEndIndex = Math.floor((i + 1) * bucketSize) + 1;

    let maxArea = -1;
    let nextPoint = data[bStartIndex];

    for (let b = bStartIndex; b < bEndIndex; b++) {
      const bPoint = data[b];
      const bLat = bPoint[0];
      const bLng = bPoint[1];

      // Декартова площадь треугольника (быстро и достаточно для GPS на малых дистанциях)
      const area = Math.abs((aLat - cAvgLat) * (bLng - aLng) - (aLat - bLat) * (cAvgLng - aLng));

      if (area > maxArea) {
        maxArea = area;
        nextPoint = bPoint;
      }
    }

    // Сохраняем ссылку на оригинальную точку
    sampled[sampledIndex++] = nextPoint;

    // Выбранная точка становится точкой A для следующего шага
    aLat = nextPoint[0];
    aLng = nextPoint[1];
  }

  // Последняя точка всегда берется из оригинала
  sampled[sampledIndex] = data[dataLen - 1];

  return sampled;
}

export default {
  getDistanceBetweenPointsInMeters,
};
